import sys
from collections import Counter

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    s = input_data[1]

    counter = Counter()
    first_occurrence = {}

    for i in range(n - 1):
        two_gram = s[i:i+2]
        if two_gram not in first_occurrence:
            first_occurrence[two_gram] = i
        counter[two_gram] += 1

    max_count = -1
    result = ""

    for two_gram in first_occurrence:
        if counter[two_gram] > max_count:
            max_count = counter[two_gram]
            result = two_gram

    print(result)

if __name__ == "__main__":
    solve()
